mapper.select:
SELECT t1.*, t2.id as stationId, t2.station_code, t2.station_name, t2.province, t2.city, t2.address, t2.station_lng, t2.station_lat, t2.station_status, t2.operator_id, t2.park_fee, t2.start_time, t2.end_time
ORDER BY t1.update_time desc
limit #{startIndex}, #{pageSize}

mapper.sql:
FROM charging_station_pile t1
LEFT JOIN charging_operator_station t2 on t2.id = t1.station_id

    t1.id is not null

        AND t2.station_lng = #{stationLng}


        AND t2.station_lat = #{stationLat}
